('g6_2_math_u1_L02_basic#1','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈으로 구해요.","나누어지는 양 ⟨3/5⟩이 앞, 얼마씩인 ⟨1/5⟩이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1,"label":"⟨3/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ + ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩ m에서 ⟨1/5⟩ m씩 덜어 내는 거예요.","몇 번 덜어 낼 수 있는지는 나눗셈이에요.","⟨4/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]}},{"stem":"물 ⟨8/9⟩ L를 한 컵에 ⟨2/9⟩ L씩 나누어 담아요. 필요한 컵의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨8/9⟩ ÷ ⟨2/9⟩","correct":true},{"t":"⟨2/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨8/9⟩ × ⟨2/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨8/9⟩ − ⟨2/9⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/9⟩ L에서 ⟨2/9⟩ L씩 덜어 내요.","같은 양을 몇 번 덜어 낼 수 있는지 — 나눗셈이에요.","⟨8/9⟩ ÷ ⟨2/9⟩예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2,"label":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내기"}]}}]}}'::jsonb),
('g6_2_math_u1_L02_basic#2','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'mc','auto','⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":2,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?","explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 3 ÷ 1 = 3.","분모 4는 답에 남지 않아요. 몫은 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"3","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"2","mis":"M6-2-u1-X03"}],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨3/4⟩에서 ⟨1/4⟩씩 덜어 내기"}]}}'::jsonb),
