('g6_2_math_u1_L02_basic#4','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"9개","mis":"M6-2-u1-X02"},{"t":"7개","mis":"M6-2-u1-X03"},{"t":"18개","mis":"M6-2-u1-X02"}],"explanation":["⟨2/9⟩는 ⟨1/9⟩ 조각을 2개 모은 수예요.","분모 9는 조각의 크기, 분자 2는 조각의 개수예요.","그래서 ⟨1/9⟩이 2개예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":2,"grp":1}]},"variant_rule":{"alt":[{"stem":"⟨3/5⟩은 ⟨1/5⟩이 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"5개","mis":"M6-2-u1-X02"},{"t":"2개","mis":"M6-2-u1-X03"},{"t":"15개","mis":"M6-2-u1-X02"}],"explanation":["⟨3/5⟩은 ⟨1/5⟩ 조각 3개예요.","분자가 조각의 개수예요.","⟨1/5⟩이 3개예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1}]}},{"stem":"⟨7/10⟩은 ⟨1/10⟩이 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"10개","mis":"M6-2-u1-X02"},{"t":"3개","mis":"M6-2-u1-X03"},{"t":"70개","mis":"M6-2-u1-X02"}],"explanation":["⟨7/10⟩은 ⟨1/10⟩ 조각 7개예요.","분자가 조각의 개수예요.","⟨1/10⟩이 7개예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":7,"grp":1}]}}]}}'::jsonb),
('g6_2_math_u1_L02_basic#5','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'sa','auto','색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.","explanation":["⟨10/20⟩을 ⟨2/20⟩씩 나누는 식은 ⟨10/20⟩ ÷ ⟨2/20⟩예요.","분모가 같으니 분자끼리 나눠요 — 10 ÷ 2 = 5.","친구는 5명 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["5","5명"]}'::jsonb),
('g6_2_math_u1_L02_basic#6','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'ox','auto','⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.","answer":"X","reason_options":[{"t":"같은 조각의 개수끼리 나누는 것이라 6 ÷ 2 = 3, 분모는 답에 남지 않아서","correct":true},{"t":"분자끼리 나누고 분모는 그대로 두어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","같은 크기의 조각이니 6 ÷ 2 = 3이에요.","몫은 3 — 분모 7은 답에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"grp":2,"label":"⟨6/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb),
('g6_2_math_u1_L02_basic#7','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨8/9⟩ ÷ ⟨2/9⟩","r":"4"},{"l":"⟨9/10⟩ ÷ ⟨3/10⟩","r":"3"},{"l":"⟨10/11⟩ ÷ ⟨5/11⟩","r":"2"}],"mis":"M6-2-u1-X02","explanation":["분모가 같으면 분자끼리 나눠요.","8 ÷ 2 = 4, 9 ÷ 3 = 3, 10 ÷ 5 = 2예요.","분모는 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨6/7⟩ ÷ ⟨3/7⟩","r":"2"},{"l":"⟨12/13⟩ ÷ ⟨2/13⟩","r":"6"},{"l":"⟨15/16⟩ ÷ ⟨3/16⟩","r":"5"}],"explanation":["분자끼리 나눠요.","6 ÷ 3 = 2, 12 ÷ 2 = 6, 15 ÷ 3 = 5예요.","분모는 몫에 남지 않아요."]}]}}'::jsonb),
('g6_2_math_u1_L02_basic#8','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',2,'mc','auto','6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X10','M6-2-u1-X02']::text[],true,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M6-2-u1-X03"},{"t":"⟨18/7⟩","mis":"M6-2-u1-X10"},{"t":"2","mis":"M6-2-u1-X02"}],"explanation":["분자 6을 3으로 나눌 수 있어요 — 6 ÷ 3 = 2.","분모는 그대로 7이에요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 (자연수)÷(자연수)예요. 4 ÷ 5의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X05"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","4 ÷ 5 = ⟨4/5⟩예요.","⟨5/4⟩로 거꾸로 적지 않도록 해요."]}]}}'::jsonb),
('g6_2_math_u1_L02_basic#9','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'mc','auto','⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":2,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?","explanation":["⟨14/15⟩는 ⟨1/15⟩이 14개, ⟨7/15⟩은 ⟨1/15⟩이 7개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 14 ÷ 7 = 2.","분모 15는 답에 남지 않아요. 몫은 2예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"2","correct":true},{"t":"⟨2/15⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X05"},{"t":"7","mis":"M6-2-u1-X03"}]}'::jsonb),
