('g6_2_math_u3_L02_challenge#3','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'error','auto','8.4 ÷ 2.1의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X19']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":3,"kind":"error","stem":"8.4 ÷ 2.1의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「8.4는 분수로 바꾸고 2.1은 소수 그대로 둬도 돼.」","correct":true,"mis_target":"M6-2-u3-X06"},{"t":"도윤 — 「두 수를 모두 분모가 10인 분수로 바꾸자.」","mis":"M6-2-u3-X19"},{"t":"수아 — 「두 수의 소수점을 똑같이 한 칸씩 옮겨도 돼.」","mis":"M6-2-u3-X19"},{"t":"지호 — 「두 수에 똑같이 10을 곱하면 84 ÷ 21이야.」","mis":"M6-2-u3-X19"}],"explanation":["분수로 바꾸든, 소수점을 옮기든, 10을 곱하든 두 수를 똑같이 바꾸는 방법이에요.","한 수만 분수로 바꾸면 분자끼리 나눌 수 없어요.","하린이는 한 수만 분수로 바꾸었어요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「4.9는 ⟨49/10⟩, 0.7은 ⟨7/100⟩로 바꾸면 돼.」","correct":true,"mis_target":"M6-2-u3-X05"},{"t":"서아 — 「두 수를 분모가 10인 분수로 바꾸면 49 ÷ 7이야.」","mis":"M6-2-u3-X19"},{"t":"도윤 — 「두 수에 똑같이 10을 곱해도 돼.」","mis":"M6-2-u3-X19"},{"t":"하린 — 「몫은 7이 될 거야.」","mis":"M6-2-u3-X19"}],"explanation":["0.7은 ⟨7/10⟩이에요.","분모가 같아야 분자끼리 나눌 수 있어요.","민준이는 분모를 서로 다르게 썼어요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#4','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'sa','auto','15 ÷ 3 = 5예요. 이것을 이용하여 1.5 ÷ 0.3의 몫을 구하면 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C1","difficulty":3,"kind":"sa","stem":"15 ÷ 3 = 5예요. 이것을 이용하여 1.5 ÷ 0.3의 몫을 구하면 얼마인가요?","answer":["5"],"explanation":["1.5 ÷ 0.3은 15 ÷ 3의 두 수를 똑같이 10으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 1.5 ÷ 0.3의 몫도 5예요."],"variant_rule":{"alt":[{"stem":"28 ÷ 7 = 4예요. 이것을 이용하여 2.8 ÷ 0.7의 몫을 구하면 얼마인가요?","answer":["4"],"explanation":["2.8 ÷ 0.7은 28 ÷ 7의 두 수를 똑같이 10으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 2.8 ÷ 0.7의 몫도 4예요."]},{"stem":"48 ÷ 6 = 8이에요. 이것을 이용하여 0.48 ÷ 0.06의 몫을 구하면 얼마인가요?","answer":["8"],"explanation":["0.48 ÷ 0.06은 48 ÷ 6의 두 수를 똑같이 100으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 0.48 ÷ 0.06의 몫도 8이에요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#5','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','다음 중 몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":5,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"다음 중 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 나누어지는 수만 바뀌어 몫이 8.1이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"7.2 ÷ 0.08","correct":true},{"t":"7.2 ÷ 0.8","mis":"M6-2-u3-X19"},{"t":"72 ÷ 8","mis":"M6-2-u3-X19"},{"t":"0.72 ÷ 0.08","mis":"M6-2-u3-X19"}],"explanation":["7.2 ÷ 0.8, 72 ÷ 8, 0.72 ÷ 0.08은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 9예요.","7.2 ÷ 0.08은 나누는 수만 작아져 몫이 90이에요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#6','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 빨간 화분의 싹이 노란 화분의 싹의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":6,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 빨간 화분의 싹이 노란 화분의 싹의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2.4에서 0.8을 한 번 빼 본다","correct":true},{"t":"cm를 mm로 바꾸어 24 ÷ 8을 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨24/10⟩ ÷ ⟨8/10⟩을 계산한다","mis":"M6-2-u3-X19"},{"t":"0.8을 몇 번 더하면 2.4가 되는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 2.4 ÷ 0.8로 구해요.","단위 바꾸기·분수로 바꾸기·몇 번 더하기는 모두 같은 생각이에요.","한 번 빼 보는 것은 차이를 구할 뿐 몇 배인지는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 엄마 범고래가 아기 범고래의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"8.24에서 4.12를 한 번 빼 본다","correct":true},{"t":"m를 cm로 바꾸어 824 ÷ 412를 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨824/100⟩ ÷ ⟨412/100⟩를 계산한다","mis":"M6-2-u3-X19"},{"t":"4.12를 몇 번 더하면 8.24가 되는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 8.24 ÷ 4.12로 구해요.","단위 바꾸기·분수로 바꾸기·몇 번 더하기는 모두 같은 생각이에요.","한 번 빼 보는 것은 차이를 구할 뿐이에요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#7','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'sa','auto','⟨72/10⟩ ÷ ⟨6/10⟩은 분자끼리 나누어 72 ÷ 6이 돼요. 7.2 ÷ 0.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C2","difficulty":3,"kind":"sa","stem":"⟨72/10⟩ ÷ ⟨6/10⟩은 분자끼리 나누어 72 ÷ 6이 돼요. 7.2 ÷ 0.6의 몫은 얼마인가요?","answer":["12"],"explanation":["7.2 ÷ 0.6은 ⟨72/10⟩ ÷ ⟨6/10⟩과 같아요.","분모가 같으니 분자끼리 72 ÷ 6이에요.","몫은 12예요."],"variant_rule":{"alt":[{"stem":"⟨84/10⟩ ÷ ⟨7/10⟩은 분자끼리 나누어 84 ÷ 7이 돼요. 8.4 ÷ 0.7의 몫은 얼마인가요?","answer":["12"],"explanation":["8.4 ÷ 0.7은 ⟨84/10⟩ ÷ ⟨7/10⟩과 같아요.","분모가 같으니 분자끼리 84 ÷ 7이에요.","몫은 12예요."]},{"stem":"⟨91/10⟩ ÷ ⟨13/10⟩은 분자끼리 나누어 91 ÷ 13이 돼요. 9.1 ÷ 1.3의 몫은 얼마인가요?","answer":["7"],"explanation":["9.1 ÷ 1.3은 ⟨91/10⟩ ÷ ⟨13/10⟩과 같아요.","분모가 같으니 분자끼리 91 ÷ 13이에요.","몫은 7이에요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#8','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',4,'mc','auto','□ ÷ 0.4의 몫은 12 ÷ 4의 몫과 같아요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":8,"concept":"M6-2-u3-C1","difficulty":4,"kind":"mc","stem":"□ ÷ 0.4의 몫은 12 ÷ 4의 몫과 같아요. □에 알맞은 수는 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-2-u3-X01"},{"t":"0.12","mis":"M6-2-u3-X02"},{"t":"120","mis":"M6-2-u3-X02"}],"explanation":["12 ÷ 4의 두 수에 똑같이 0.1을 곱하면 1.2 ÷ 0.4예요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 □는 1.2예요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.07의 몫은 63 ÷ 7의 몫과 같아요. □에 알맞은 수는 얼마인가요?","options":[{"t":"0.63","correct":true},{"t":"63","mis":"M6-2-u3-X01"},{"t":"6.3","mis":"M6-2-u3-X02"},{"t":"0.063","mis":"M6-2-u3-X02"}],"explanation":["63 ÷ 7의 두 수에 똑같이 0.01을 곱하면 0.63 ÷ 0.07이에요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 □는 0.63이에요."]}]}}'::jsonb),
('g6_2_math_u3_L02_challenge#9','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',4,'essay','teacher','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 ÷ 0.8을 cm를 mm로 바꾸어 계산하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C1","difficulty":4,"kind":"essay","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 ÷ 0.8을 cm를 mm로 바꾸어 계산하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2.4 cm는 24 mm, 0.8 cm는 8 mm이므로 24 ÷ 8 = 3이다. 단위를 바꾸면 두 수가 똑같이 10배가 되는데, 두 수에 똑같은 수를 곱하면 몫은 그대로이므로 2.4 ÷ 0.8의 몫도 3이다.","scoring_points":["24 ÷ 8 = 3을 썼는가","두 수가 똑같이 10배가 되었음을 밝혔는가","두 수에 같은 수를 곱해도 몫은 그대로라는 까닭을 썼는가"]},"explanation":["2.4 cm는 24 mm, 0.8 cm는 8 mm예요.","두 수가 똑같이 10배가 되었어요.","그래서 몫은 그대로 — 24 ÷ 8 = 3이에요."]}'::jsonb),
('g6_2_math_u3_L02_challenge#10','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',4,'essay','teacher','7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C2","difficulty":4,"kind":"essay","stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이므로 ⟨72/10⟩ ÷ ⟨6/10⟩ = 72 ÷ 6 = 12이다. 분모가 같아야 같은 크기의 조각 개수끼리 나눌 수 있어 분자끼리 나눌 수 있다.","scoring_points":["⟨72/10⟩ ÷ ⟨6/10⟩으로 바꾸었는가","72 ÷ 6 = 12를 구했는가","분모가 같아야 분자끼리 나눌 수 있다는 까닭을 썼는가"]},"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","분모가 같으면 분자끼리 72 ÷ 6이에요.","몫은 12예요."]}'::jsonb),
('g6_2_math_u3_L03_basic#1','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.6이 정해요.","0.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#2','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'mc','auto','8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":2,"concept":"M6-2-u3-C3","difficulty":1,"kind":"mc","stem":"8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"84 ÷ 21","correct":true},{"t":"8.4 ÷ 21","mis":"M6-2-u3-X01"},{"t":"84 ÷ 2.1","mis":"M6-2-u3-X01"},{"t":"840 ÷ 21","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.1이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8.4도 똑같이 한 칸 옮겨요.","그래서 84 ÷ 21이 돼요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"36 ÷ 5","correct":true},{"t":"3.6 ÷ 5","mis":"M6-2-u3-X01"},{"t":"36 ÷ 0.5","mis":"M6-2-u3-X01"},{"t":"360 ÷ 5","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 0.5가 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 3.6도 똑같이 한 칸 옮겨요.","그래서 36 ÷ 5가 돼요."]},{"stem":"9.1 ÷ 1.3에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"91 ÷ 13","correct":true},{"t":"9.1 ÷ 13","mis":"M6-2-u3-X01"},{"t":"91 ÷ 1.3","mis":"M6-2-u3-X01"},{"t":"910 ÷ 13","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.3이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 9.1도 똑같이 한 칸 옮겨요.","그래서 91 ÷ 13이 돼요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#3','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','4.9 ÷ 0.7의 몫은 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"4.9 ÷ 0.7의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.9 ÷ 0.7은 49 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","49 ÷ 7 = 7이에요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 2.1의 몫은 얼마인가요?","answer":["4"],"explanation":["나누는 수 2.1이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","8.4 ÷ 2.1은 84 ÷ 21이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","84 ÷ 21 = 4예요."]},{"stem":"5.6 ÷ 0.8의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 0.8이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.6 ÷ 0.8은 56 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","56 ÷ 8 = 7이에요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#4','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','7.2 ÷ 0.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"7.2 ÷ 0.6의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","7.2 ÷ 0.6은 72 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","72 ÷ 6 = 12예요."],"variant_rule":{"alt":[{"stem":"9.6 ÷ 0.8의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.8이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.6 ÷ 0.8은 96 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","96 ÷ 8 = 12예요."]},{"stem":"6.5 ÷ 0.5의 몫은 얼마인가요?","answer":["13"],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.5 ÷ 0.5는 65 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","65 ÷ 5 = 13이에요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#5','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5를 세로로 계산할 때 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":5,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5를 세로로 계산할 때 잘못된 것은 어느 것인가요?","options":[{"t":"3.6 ÷ 5로 바꾼다","correct":true},{"t":"36 ÷ 5로 바꾼다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 10을 곱한다","mis":"M6-2-u3-X19"}],"explanation":["나누는 수 0.5가 자연수가 되도록 한 칸 옮기면 5예요.","나누어지는 수 3.6도 똑같이 한 칸 옮겨 36이 돼요.","3.6 ÷ 5는 나누는 수만 옮긴 다른 나눗셈이에요."],"variant_rule":{"alt":[{"stem":"4.2 ÷ 0.6을 세로로 계산할 때 잘못된 것은 어느 것인가요?","options":[{"t":"4.2 ÷ 6으로 바꾼다","correct":true},{"t":"42 ÷ 6으로 바꾼다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 10을 곱한다","mis":"M6-2-u3-X19"}],"explanation":["0.6이 자연수가 되도록 한 칸 옮기면 6이에요.","4.2도 똑같이 한 칸 옮겨 42가 돼요.","4.2 ÷ 6은 나누는 수만 옮긴 다른 나눗셈이에요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#6','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"0.072","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."],"variant_rule":{"alt":[{"stem":"4.5 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.5 ÷ 0.6은 45 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]},{"stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#7','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?","options":[{"t":"옮긴 소수점의 위치","correct":true},{"t":"나누어지는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"나누는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"몫의 맨 뒤","mis":"M6-2-u3-X04"}],"explanation":["두 수의 소수점을 옮기면 자연수의 나눗셈처럼 계산해요.","몫은 옮긴 나눗셈의 몫과 같아요.","그래서 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 36 ÷ 5로 바꾸어 세로로 계산했어요. 몫의 소수점은 어디에서 위로 올려 찍나요?","options":[{"t":"36의 소수점 자리(옮긴 자리)","correct":true},{"t":"3.6의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"0.5의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"몫의 맨 뒤","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5와 36 ÷ 5는 몫이 같아요.","그래서 옮긴 자리를 기준으로 계산해요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#8','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'ox','auto','8.4 ÷ 2.1과 84 ÷ 21의 몫은 같아요.',ARRAY['M6-2-u3-X01']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":2,"kind":"ox","stem":"8.4 ÷ 2.1과 84 ÷ 21의 몫은 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10을 곱한 사이이기 때문에","correct":true},{"t":"나누어지는 수만 10배가 되었기 때문에","mis":"M6-2-u3-X01"}],"mis":"M6-2-u3-X01","explanation":["8.4와 2.1의 소수점을 똑같이 한 칸 옮기면 84와 21이에요.","두 수에 똑같이 10을 곱했어요.","그래서 몫은 4로 같아요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6과 72 ÷ 6의 몫은 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10을 곱한 사이이기 때문에","correct":true},{"t":"나누는 수만 10배가 되었기 때문에","mis":"M6-2-u3-X01"}],"explanation":["7.2와 0.6의 소수점을 똑같이 한 칸 옮기면 72와 6이에요.","두 수에 똑같이 10을 곱했어요.","그래서 몫은 12로 같아요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#9','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'sa','auto','분홍색 리본 4.8 m를 0.6 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"분홍색 리본 4.8 m를 0.6 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?","answer":["8"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.8 ÷ 0.6은 48 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","48 ÷ 6 = 8이에요."],"variant_rule":{"alt":[{"stem":"분홍색 리본 6.3 m를 0.7 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?","answer":["9"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 0.7은 63 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","63 ÷ 7 = 9예요."]}]}}'::jsonb),
('g6_2_math_u3_L03_basic#10','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4.9 ÷ 0.7","r":"7"},{"l":"3.6 ÷ 0.5","r":"7.2"},{"l":"19.2 ÷ 2.4","r":"8"}],"mis":"M6-2-u3-X03","explanation":["4.9 ÷ 0.7 = 49 ÷ 7 = 7이에요.","3.6 ÷ 0.5 = 36 ÷ 5 = 7.2예요.","19.2 ÷ 2.4 = 192 ÷ 24 = 8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7.2 ÷ 0.6","r":"12"},{"l":"4.5 ÷ 0.6","r":"7.5"},{"l":"2.7 ÷ 0.9","r":"3"}],"explanation":["7.2 ÷ 0.6 = 72 ÷ 6 = 12예요.","4.5 ÷ 0.6 = 45 ÷ 6 = 7.5예요.","2.7 ÷ 0.9 = 27 ÷ 9 = 3이에요."]}]}}'::jsonb),
('g6_2_math_u3_L03_challenge#1','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',2,'sa','auto','24.5 ÷ 3.5의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"24.5 ÷ 3.5의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 3.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","24.5 ÷ 3.5는 245 ÷ 35가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","245 ÷ 35 = 7이에요."],"variant_rule":{"alt":[{"stem":"19.2 ÷ 2.4의 몫은 얼마인가요?","answer":["8"],"explanation":["나누는 수 2.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","19.2 ÷ 2.4는 192 ÷ 24가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","192 ÷ 24 = 8이에요."]},{"stem":"28.8 ÷ 3.6의 몫은 얼마인가요?","answer":["8"],"explanation":["나누는 수 3.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","28.8 ÷ 3.6은 288 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","288 ÷ 36 = 8이에요."]}]}}'::jsonb),
