('g6_2_math_u3_review_c#15','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"5.4 ÷ 4.5","correct":true},{"t":"5.4 ÷ 0.45","mis":"M6-2-u3-X19"},{"t":"540 ÷ 45","mis":"M6-2-u3-X19"},{"t":"54 ÷ 4.5","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45, 540 ÷ 45, 54 ÷ 4.5는 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 12예요.","5.4 ÷ 4.5는 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"2.55 ÷ 0.15","correct":true},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"25.5 ÷ 15","mis":"M6-2-u3-X19"},{"t":"255 ÷ 150","mis":"M6-2-u3-X19"}],"explanation":["2.55 ÷ 1.5, 25.5 ÷ 15, 255 ÷ 150은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 1.7이에요.","2.55 ÷ 0.15는 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb),
('g6_2_math_u3_review_c#16','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',1,'sa','auto','7 ÷ 1.75의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["나누어지는 수 7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."]},{"stem":"8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."]}]}}'::jsonb),
