('g6_2_math_u3_review_d#21','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."]}]}}'::jsonb),
('g6_2_math_u3_review_d#22','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',3,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["3.38 ÷ 0.9 = 3.755…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 3.8이에요."],"variant_rule":{"alt":[{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 0.17이에요."]},{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 0.3이에요."]}]}}'::jsonb),
('g6_2_math_u3_review_d#23','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]}]}}'::jsonb),
('g6_2_math_u3_review_d#24','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]}]}}'::jsonb),
('g6_2_math_u3_review_d#25','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.8 = 5.66…이므로 5명에게 나누어 줄 수 있다. 나누어 준 주스는 1.8 × 5 = 9 L이고 남는 주스는 10.2 − 9 = 1.2 L이다. 몫을 반올림해 6명으로 하면 10.8 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["5명을 구했는가","남는 주스 1.2 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["10.2 ÷ 1.8 = 5.66… — 5명이에요.","남는 양은 10.2 − 9 = 1.2 (L)예요.","6명이면 10.8 L가 필요해 모자라요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M6-2-u4-C1','math',6,2,'u4',2,'비의 성질 — 비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 같은 수로 나누어도 비율은 같음을 알고(같은 수를 더하는 것은 성질이 아님), 전항·후항·비율을 바르게 읽기',ARRAY['6수04-02']::text[],1),
('M6-2-u4-C2','math',6,2,'u4',3,'자연수의 비를 간단한 자연수의 비로 나타내기 — 두 항의 공약수로 더 나눌 수 없을 때까지(최대공약수로) 나누기',ARRAY['6수04-02']::text[],2),
('M6-2-u4-C3','math',6,2,'u4',3,'소수의 비를 간단한 자연수의 비로 나타내기 — 두 항이 모두 자연수가 되도록 10·100을 곱한 뒤 공약수로 나누기',ARRAY['6수04-02']::text[],3),
('M6-2-u4-C4','math',6,2,'u4',3,'분수의 비와 소수·분수가 섞인 비를 간단한 자연수의 비로 나타내기 — 두 분모의 공배수를 곱하거나, 한쪽을 소수(분수)로 바꾸어 같은 꼴로 만든 뒤 나타내기',ARRAY['6수04-02']::text[],4),
('M6-2-u4-C5','math',6,2,'u4',4,'비례식과 외항·내항 — 비율이 같은 두 비를 등호로 이은 식을 비례식이라 하고, 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라 하며, 비례식인지는 수의 모양이 아니라 비율로 판단하기',ARRAY['6수04-02']::text[],5),
('M6-2-u4-C6','math',6,2,'u4',5,'비례식의 성질 — 비례식에서 외항의 곱과 내항의 곱이 같음을 알고, 이를 이용하여 □가 있는 비례식을 풀거나 비례식인지 확인하기',ARRAY['6수04-02']::text[],6),
('M6-2-u4-C7','math',6,2,'u4',6,'비례식을 세워 생활 문제 해결하기 — 함께 같은 비율로 변하는 두 양에서 구하려는 것을 □로 두고 대응이 맞게 비례식을 세운 뒤 비례식의 성질이나 비의 성질로 풀기',ARRAY['6수04-02']::text[],7),
('M6-2-u4-C8','math',6,2,'u4',7,'비례배분 — 전체를 가：나로 배분할 때 전체를 (가+나)칸으로 갈라 전체 × (가 ÷ (가+나)), 전체 × (나 ÷ (가+나))로 구하기',ARRAY['6수04-02']::text[],8),
('M6-2-u4-C9','math',6,2,'u4',8,'비례배분 활용 — 먼저 전체에서 우리 몫을 비례배분한 뒤 그 몫을 다시 정한 기준(낸 금액·만든 수 등)의 비로 나누고, 기준에 따라 몫이 달라짐을 알기',ARRAY['6수04-02']::text[],9)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M6-2-u4-X01','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C5']::text[],'전항과 후항에 같은 수를 더하거나 빼도 비율이 같다고 본다(2：3에 2를 더해 4：5)','더하기는 비의 성질이 아니에요'),
('M6-2-u4-X02','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'전항과 후항 가운데 한 항에만 곱하거나 한 항만 나눈다','두 항을 똑같이'),
('M6-2-u4-X03','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5']::text[],'전항과 후항(비교하는 양과 기준량)을 바꾸어 쓰거나 비율의 기준량을 잘못 잡는다','「무엇에 대한」 쪽이 뒤'),
('M6-2-u4-X04','math',6,'u4',ARRAY['M6-2-u4-C1']::text[],'전항과 후항에 0을 곱하거나 0으로 나누어도 된다고 본다','0이 아닌 같은 수만'),
('M6-2-u4-X05','math',6,'u4',ARRAY['M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'공약수로 끝까지 나누지 않아 가장 간단한 자연수의 비가 아닌 채로 멈춘다','더 나눌 공약수가 있나요?'),
('M6-2-u4-X06','math',6,'u4',ARRAY['M6-2-u4-C3','M6-2-u4-C4']::text[],'소수의 비에서 곱하는 수를 잘못 정해(한 자리 수에만 맞춰 10만 곱하는 등) 자연수가 되지 않거나 비가 달라진다','두 항이 모두 자연수가 되도록'),
('M6-2-u4-X07','math',6,'u4',ARRAY['M6-2-u4-C4']::text[],'분수의 비에서 분모끼리 또는 분자끼리만 떼어 비로 쓴다(⟨1/5⟩：⟨1/7⟩을 5：7이나 1：1로)','두 분모의 공배수를 곱해요'),
('M6-2-u4-X09','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'두 비의 수 모양만 보고(같은 수가 들어 있으면) 비례식이라고 판단한다(7：4 = 4：7)','비율을 견주어 봐요'),
('M6-2-u4-X10','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'외항과 내항을 바꾸어 안다(안쪽 두 수를 외항으로)','바깥 둘이 외항'),
('M6-2-u4-X11','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱한다','바깥끼리, 안쪽끼리'),
('M6-2-u4-X12','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항의 곱과 내항의 곱을 같게 놓은 뒤 □를 구하지 않고 곱한 값을 답으로 쓰거나 나눗셈을 잘못한다','곱 ÷ 아는 수 = □'),
('M6-2-u4-X13','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'비례식을 세울 때 대응을 어긋나게 놓는다(2：8000 = 40000：★처럼 무게와 값의 자리를 바꿈)','같은 종류끼리 같은 자리'),
('M6-2-u4-X14','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'두 양이 같은 비율로 변하는지 보지 않고 차이(더하기·빼기)로 늘린다','몇 배가 되었는지 봐요'),
('M6-2-u4-X15','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 전체를 비의 한 항(가 또는 나)으로 나눈다(1200을 2：3으로 → 1200 ÷ 2)','한 묶음은 (가+나)칸'),
('M6-2-u4-X16','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 (가 ÷ (가+나)) 대신 (가 ÷ 나)를 곱하거나 한 칸의 양을 답으로 쓴다','분모는 가+나'),
('M6-2-u4-X17','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분한 두 몫 가운데 다른 쪽의 몫을 답으로 쓴다','누구의 몫을 묻나요?'),
('M6-2-u4-X18','math',6,'u4',ARRAY['M6-2-u4-C9']::text[],'두 번 나누어야 할 때 첫 단계(전체에서 우리 몫)를 건너뛰고 전체를 바로 나눈다','먼저 우리 몫부터'),
('M6-2-u4-X19','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'묻는 말을 거꾸로 읽는다 — 알맞은↔알맞지 않은, 외항↔내항, 큰↔작은','물음의 「않은·잘못」에 동그라미'),
('M6-2-u4-X20','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'곱셈·나눗셈·약분 계산을 잘못한다','거꾸로 곱해서 확인')
